"""Account, direct-comment, reporting and manual-observation exhibition journeys."""
import os,json
from playwright.sync_api import sync_playwright
BASE=os.environ.get('WN_TEST_BASE','http://127.0.0.1:8080/')
def login(page,role='resident'):
 page.goto(BASE+'fencepost/index.html#login');page.get_by_role('button',name='Use '+role+' account',exact=True).click();page.get_by_role('button',name='Sign in',exact=True).click();page.get_by_role('heading',name='Moderator dashboard' if role=='moderator' else 'Hello, Taylor',exact=True).wait_for()
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);ctx=b.new_context(viewport={'width':390,'height':844});page=ctx.new_page();errors=[];page.on('pageerror',lambda e:errors.append(str(e)))
 page.goto(BASE+'fencepost/index.html#stories');page.get_by_role('heading',name='Wildlife stories from your neighbourhood').wait_for()
 page.goto(BASE+'fencepost/index.html#moderator/pending');page.get_by_role('heading',name='Sign in to Fencepost').wait_for();assert not page.locator('.moderation-form').count()
 page.get_by_role('button',name='Use resident account').click();assert 'login' in page.url
 page.locator('#account-login [name=password]').fill('incorrect');page.get_by_role('button',name='Sign in',exact=True).click();page.get_by_text('The email or password is incorrect.',exact=False).wait_for()
 login(page);page.reload();page.get_by_role('heading',name='Hello, Taylor',exact=True).wait_for();session=page.evaluate("JSON.parse(localStorage.getItem('wn-demo-session'))");assert set(session)=={'id','displayName','email','role'}
 all_storage=page.evaluate('JSON.stringify(Object.fromEntries(Object.entries(localStorage)))');assert 'resident123' not in all_storage and 'moderator123' not in all_storage
 page.goto(BASE+'fencepost/index.html#my-observations');page.get_by_role('heading',name='My observations',exact=True).wait_for();assert 'Awaiting review' in page.inner_text('#content');assert 'DEMO PRIVATE LOCATION' not in page.inner_text('#content')
 page.goto(BASE+'fencepost/index.html#moderator/reports');page.get_by_role('heading',name='Moderator access is required.').wait_for();assert not page.locator('.moderation-form').count()
 print('Guest browsing, guarded routes, incorrect credentials, resident refresh and safe stored session passed',flush=True)
 page.goto(BASE+'fencepost/index.html#story/story-brushtail');page.locator('#comment-form').wait_for();page.locator('#comment-form [name=body]').fill('I watched quietly from the path.');page.get_by_role('button',name='Post comment',exact=True).click();page.get_by_text('Your comment is visible now.',exact=True).wait_for();card=page.locator('.comment-card').filter(has_text='I watched quietly from the path.');card.wait_for();card.get_by_role('button',name='Edit',exact=True).click();page.locator('#comment-form [name=body]').fill('I watched calmly from the path.');page.get_by_role('button',name='Save comment',exact=True).click();page.get_by_text('Your comment is visible now.',exact=True).wait_for();page.locator('.comment-card').filter(has_text='I watched calmly from the path.').get_by_role('button',name='Delete',exact=True).click();page.get_by_text('Your comment was deleted.',exact=True).wait_for();assert not page.locator('.comment-card').filter(has_text='I watched calmly from the path.').count()
 page.locator('#comment-form [name=body]').fill('Find the animal at 12 Acacia Street');page.get_by_role('button',name='Post comment',exact=True).click();assert 'Remove exact addresses' in page.locator('#comment-validation').inner_text()
 target=page.locator('#comment-comment-neighbour-demo');assert not target.get_by_role('button',name='Edit',exact=True).count();target.get_by_role('button',name='Report',exact=True).click();page.locator('#report-form [name=reason]').select_option('Other concern');page.get_by_role('button',name='Send report',exact=True).click();page.get_by_text('Thanks for letting us know.',exact=False).wait_for();assert page.locator('#comment-comment-neighbour-demo').count()==1
 print('Immediate comments, own edit/delete, validation and report-without-hiding passed',flush=True)
 page.goto(BASE+'fencepost/index.html#share');page.locator('[name=behaviour]').fill('Resting in a tree');original='saw a possible possum resting in the park';page.locator('[name=description]').fill(original)
 page.locator('[name=safeConsent]').check();page.get_by_role('button',name='Preview submission',exact=True).click();page.get_by_role('button',name='Send for review',exact=True).click();page.get_by_role('heading',name='Sent for review — not yet public',exact=True).wait_for()
 print('Manual text-only observation preview and submission passed',flush=True)
 login(page,'moderator');page.goto(BASE+'fencepost/index.html#moderator/pending');page.get_by_role('heading',name='Posts awaiting approval',exact=True).wait_for();form=page.locator('.moderation-form').filter(has=page.locator('textarea[name=publicText]',has_text=original));form.locator('xpath=..').locator('summary').click()
 for key in ['face','house','plate','location','welfare']:form.locator('[name='+key+']').check()
 form.locator('[name=reason]').fill('Human privacy review completed.');form.get_by_role('button',name='Approve and publish',exact=True).click();page.get_by_text('Moderation action recorded.',exact=True).wait_for();page.goto(BASE+'index.html');page.get_by_text(original,exact=True).wait_for()
 page.goto(BASE+'fencepost/index.html#moderator/reports');page.get_by_role('heading',name='Reported Comments',exact=True).wait_for();report=page.locator('.admin-content article').filter(has_text='A good reminder to keep pets close');form=report.locator('.comment-moderation');form.locator('[name=reason]').fill('Sample comment removed after review.');form.get_by_role('button',name='Remove comment',exact=True).click();page.get_by_text('Comment action recorded.',exact=True).wait_for();
 report=page.locator('.admin-content article').filter(has_text='A good reminder to keep pets close');report.get_by_role('button',name='Restore comment',exact=True).click();page.get_by_text('Comment action recorded.',exact=True).wait_for()
 page.goto(BASE+'fencepost/index.html#moderator/settings');page.on('dialog',lambda dialog:dialog.accept());page.get_by_role('button',name='Reset demonstration data',exact=True).click();page.get_by_role('heading',name='Moderator dashboard',exact=True).wait_for();assert page.evaluate("JSON.parse(localStorage.getItem('wn-demo-session')).role")=='moderator'
 print('Moderator post approval, reported-comment remove/restore and authenticated reset passed',flush=True)
 page.get_by_role('button',name='Logout',exact=True).click();page.get_by_role('heading',name='Wildlife stories from your neighbourhood').wait_for();assert page.evaluate("localStorage.getItem('wn-demo-session')") is None
 assert page.evaluate('document.documentElement.scrollWidth<=innerWidth');assert not errors,errors
 print('Logout, mobile layout and no JavaScript errors passed',flush=True);b.close()
